CREATE TABLE inbox_channels(sender_id text PRIMARY KEY,organisation_id uuid NOT NULL REFERENCES organisations(id),business_id text NOT NULL,created_at timestamptz(3) NOT NULL);
CREATE TABLE inbox_threads(id uuid PRIMARY KEY,organisation_id uuid NOT NULL REFERENCES organisations(id),sender_id text NOT NULL REFERENCES inbox_channels(sender_id),contact_key text NOT NULL,phone_cipher text NOT NULL,last4 text NOT NULL,last_inbound_at timestamptz(3) NOT NULL,stopped_at timestamptz(3),opted_in_at timestamptz(3),opt_in_source text,assigned_doctor_id uuid REFERENCES users(id),state text NOT NULL DEFAULT 'open' CHECK(state IN ('open','resolved')),unread integer NOT NULL DEFAULT 0 CHECK(unread>=0),revision integer NOT NULL DEFAULT 1,updated_at timestamptz(3) NOT NULL,UNIQUE(sender_id,contact_key));
CREATE INDEX inbox_threads_organisation_id_updated_at_idx ON inbox_threads(organisation_id,updated_at);
CREATE TABLE inbox_templates(id uuid PRIMARY KEY,organisation_id uuid NOT NULL REFERENCES organisations(id),sender_id text NOT NULL REFERENCES inbox_channels(sender_id),provider_id text NOT NULL,name text NOT NULL,language text NOT NULL,category text NOT NULL,provider_status text NOT NULL,body_cipher text NOT NULL,content_hash text NOT NULL,supported boolean NOT NULL,enabled boolean NOT NULL DEFAULT false,revision integer NOT NULL DEFAULT 1,verified_at timestamptz(3) NOT NULL,UNIQUE(sender_id,provider_id));
CREATE TABLE inbox_messages(id uuid PRIMARY KEY,organisation_id uuid NOT NULL REFERENCES organisations(id),thread_id uuid NOT NULL REFERENCES inbox_threads(id),sender_id text NOT NULL REFERENCES inbox_channels(sender_id),provider_id text,direction text NOT NULL CHECK(direction IN ('inbound','outbound')),kind text NOT NULL CHECK(kind IN ('text','unsupported','template')),body_cipher text NOT NULL,input_hash text,state text NOT NULL CHECK(state IN ('received','queued','sending','accepted','sent','delivered','read','failed','uncertain','skipped')),occurred_at timestamptz(3) NOT NULL,created_at timestamptz(3) NOT NULL,attempt_at timestamptz(3),status_at timestamptz(3) NOT NULL,sent_by_user_id uuid REFERENCES users(id),sent_by_role text,template_id uuid REFERENCES inbox_templates(id),template_revision integer,error_code integer,UNIQUE(sender_id,provider_id));
CREATE INDEX inbox_messages_thread_id_created_at_idx ON inbox_messages(thread_id,created_at);
CREATE INDEX inbox_messages_organisation_id_state_created_at_idx ON inbox_messages(organisation_id,state,created_at);
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['inbox_channels','inbox_threads','inbox_messages','inbox_templates'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('GRANT SELECT,INSERT,UPDATE ON %I TO dhc_app',t);EXECUTE format('CREATE POLICY tenant_isolation ON %I TO dhc_app USING(organisation_id=app_current_organisation_id()) WITH CHECK(organisation_id=app_current_organisation_id())',t);END LOOP;END $$;
CREATE FUNCTION inbox_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Inbox history is retained'; END IF;
 IF TG_TABLE_NAME='inbox_channels' THEN
  IF TG_OP='UPDATE' AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'Inbox channel bindings are immutable'; END IF; RETURN NEW;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM inbox_channels WHERE sender_id=NEW.sender_id AND organisation_id=NEW.organisation_id) THEN RAISE EXCEPTION 'Inbox sender belongs to another clinic';END IF;
 IF TG_OP='UPDATE' AND (NEW.id,NEW.organisation_id,NEW.sender_id) IS DISTINCT FROM (OLD.id,OLD.organisation_id,OLD.sender_id) THEN RAISE EXCEPTION 'Inbox identity is immutable'; END IF;
 IF TG_TABLE_NAME='inbox_threads' THEN IF NEW.assigned_doctor_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM memberships WHERE organisation_id=NEW.organisation_id AND user_id=NEW.assigned_doctor_id AND role='doctor') THEN RAISE EXCEPTION 'Inbox doctor belongs to another clinic';END IF; IF TG_OP='UPDATE' AND (NEW.contact_key,NEW.phone_cipher,NEW.last4) IS DISTINCT FROM (OLD.contact_key,OLD.phone_cipher,OLD.last4) THEN RAISE EXCEPTION 'Inbox contact is immutable';END IF;END IF;
 IF TG_TABLE_NAME='inbox_messages' THEN
  IF NEW.template_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM inbox_templates WHERE id=NEW.template_id AND organisation_id=NEW.organisation_id AND sender_id=NEW.sender_id) THEN RAISE EXCEPTION 'Inbox template belongs to another clinic';END IF;
  IF NEW.direction='outbound' AND (NEW.sent_by_user_id IS NULL OR NEW.sent_by_role IS NULL OR NOT EXISTS(SELECT 1 FROM memberships WHERE organisation_id=NEW.organisation_id AND user_id=NEW.sent_by_user_id AND role::text=NEW.sent_by_role)) THEN RAISE EXCEPTION 'Inbox sender belongs to another clinic';END IF;
  IF NOT EXISTS(SELECT 1 FROM inbox_threads WHERE id=NEW.thread_id AND organisation_id=NEW.organisation_id AND sender_id=NEW.sender_id) THEN RAISE EXCEPTION 'Inbox thread belongs to another clinic';END IF;
  IF TG_OP='UPDATE' AND ((NEW.thread_id,NEW.direction,NEW.kind,NEW.body_cipher,NEW.input_hash,NEW.occurred_at,NEW.created_at,NEW.sent_by_user_id,NEW.sent_by_role,NEW.template_id,NEW.template_revision) IS DISTINCT FROM (OLD.thread_id,OLD.direction,OLD.kind,OLD.body_cipher,OLD.input_hash,OLD.occurred_at,OLD.created_at,OLD.sent_by_user_id,OLD.sent_by_role,OLD.template_id,OLD.template_revision) OR (OLD.provider_id IS NOT NULL AND NEW.provider_id IS DISTINCT FROM OLD.provider_id)) THEN RAISE EXCEPTION 'Inbox message content is immutable';END IF;
 END IF;RETURN NEW;END $$;
CREATE TRIGGER inbox_guard BEFORE UPDATE OR DELETE ON inbox_channels FOR EACH ROW EXECUTE FUNCTION inbox_guard();
CREATE TRIGGER inbox_guard BEFORE INSERT OR UPDATE OR DELETE ON inbox_threads FOR EACH ROW EXECUTE FUNCTION inbox_guard();
CREATE TRIGGER inbox_guard BEFORE INSERT OR UPDATE OR DELETE ON inbox_messages FOR EACH ROW EXECUTE FUNCTION inbox_guard();
CREATE TRIGGER inbox_guard BEFORE INSERT OR UPDATE OR DELETE ON inbox_templates FOR EACH ROW EXECUTE FUNCTION inbox_guard();
